		TrackPart(const CPoint_AC& mouseLocation, 									ControlPartCode partHit);	void						HandleControlAction(ControlPartCode partHit);		inline SInt16 MinSInt16(SInt16 a, SInt16 b) { return (a < b) ? a : b; }	inline SInt16 MaxSInt16(SInt16 a, SInt16 b) { return (a > b) ? a : b; }	inline SInt32 MinSInt32(SInt32 a, SInt32 b) { return (a < b) ? a : b; }	inline SInt32 MaxSInt32(SInt32 a, SInt32 b) { return (a > b) ? a : b; }		CRect_AC	fBounds;	bool		fActive;	// if false, draws with dim appearance, ignores mouse clicks	bool		fVisible;	// if false, no drawing occurs.	};//----------------------------------------------------------------------------------------// CCustomButton_AC//----------------------------------------------------------------------------------------class EXPORT_AC CCustomButton_AC : public CCustomControl_AC// This class implements basic button properties to a custom control.// A button automatically hilites itself while tracking the mouse.{public:	CCustomButton_AC(const CRect_AC& boundsRect, 					 bool isActive,					 const CStr255_AC& itsTitle = kEmptyString_AC,					 const CTextStyle_AC& titleStyle = CTextStyle_AC::kSystemStyle);												virtual ~CCustomButton_AC();		virtual void				DrawControl();		// Calls DrawButton(kNotPressed);		virtual CStr255_AC			GetTitle() const;	virtual void				SetTitle(const CStr255_AC& newTitle);		// Get and set the title for the control.	virtual void				SetPartHilite(ControlPartCode part, bool isHilited);		// Set the hilite state for this control and redraw if needed.			virtual void 				 SetFontStyle(const CControlTextStyle_AC& textStyle);	virtual CControlTextStyle_AC GetFontStyle();		// Get and set the font style for this button.		protected:	void						DrawButton(bool pressed);		// Calls the virtual functions according to state.			virtual void				DrawButtonNormal(bool deep) = 0;	virtual void				DrawButtonPressed(bool deep) = 0;	virtual void				DrawButtonDisabled(bool deep) = 0;protected:	CStr255_AC fTitle;	CTextStyle_AC fTitleStyle;};#endif // qEmulateStandardControls//----------------------------------------------------------------------------------------// MControlBackground_AC//----------------------------------------------------------------------------------------class EXPORT_AC MControlBackground_AC// This class implements mixin support for background colors.// Previously, all custom controls kept this information even though only// a few used it for calls to PaintRect, but now only a couple of// views that manipulate the background colors require this class,// and the rest use the current background color.{public:	enum { kInstallOnlyIfCustom = false, kInstallAlways = true };	MControlBackground_AC(bool installIfNotCustom);	virtual ~MControlBackground_AC();	void				InstallBackgroundColors(bool installIfNotCustom);		// Determines the background colors and then sets the background color fields.	void				SetBackgroundColors(const CRGBColor_AC& enabledColor, const CRGBColor_AC& disabledColor);		// Sets the background color fields.  Not normally called directly.			void				ApplyBackgroundColor(bool isEnabled);		// Sets the foreground color for PaintRect.	static void			TurnOnCustomBackgroundColors(const CRGBColor_AC& enabledColor, const CRGBColor_AC& disabledColor);	static void			TurnOffCustomBackgroundColors();		// Controls the use of background colors during control creation.			static bool			DetermineBackgroundColors(CRGBColor_AC& enabledColor, CRGBColor_AC& disabledColor, 												  bool installIfNotCustom = kInstallOnlyIfCustom);		// Determines the background colors.  Not normally called directly.		protected:		CRGBColor_AC	fEnabledBackgroundColor;	CRGBColor_AC	fDisabledBackgroundColor;		static bool			fgUseSpecialBackgroundColors;	static CRGBColor_AC fgEnabledBackgroundColor;	static CRGBColor_AC fgDisabledBackgroundColor;};#endif // __CCustomControl_AC__